class Solution {
public:
    int longestFrequencyBalance(vector<int>& nums) {
        int n = nums.size(), ans = 1;
        for (int i = 0; i < n; i++) {
            unordered_map<int,int> cnt;
            for (int j = i; j < n; j++) {
                cnt[nums[j]]++;
                set<int> fs;
                for (auto& p : cnt) fs.insert(p.second);
                bool ok = cnt.size() == 1;
                if (!ok && fs.size() == 2) {
                    auto it = fs.begin();
                    int a = *it; ++it; int b = *it;
                    ok = (b == 2 * a);
                }
                if (ok) ans = max(ans, j - i + 1);
            }
        }
        return ans;
    }
};

