class Solution {
    public int longestFrequencyBalance(int[] nums) {
        int n = nums.length, ans = 1;
        for (int i = 0; i < n; i++) {
            Map<Integer,Integer> cnt = new HashMap<>();
            for (int j = i; j < n; j++) {
                cnt.merge(nums[j], 1, Integer::sum);
                TreeSet<Integer> fs = new TreeSet<>(cnt.values());
                boolean ok = cnt.size() == 1;
                if (!ok && fs.size() == 2) {
                    Iterator<Integer> it = fs.iterator();
                    int a = it.next(), b = it.next();
                    ok = (b == 2L * a);
                }
                if (ok) ans = Math.max(ans, j - i + 1);
            }
        }
        return ans;
    }
}

