class Solution {
    public int longestFrequencyBalance(int[] nums) {
        int n = nums.length, ans = 1;
        for (int i = 0; i < n; i++) {
            Map<Integer,Integer> cnt = new HashMap<>(), fc = new HashMap<>();
            int d = 0;
            for (int j = i; j < n; j++) {
                int x = nums[j];
                int f = cnt.getOrDefault(x, 0);
                if (f == 0) d++;
                else if (fc.merge(f, -1, Integer::sum) == 0) fc.remove(f);
                cnt.put(x, f + 1);
                fc.merge(f + 1, 1, Integer::sum);
                if (d == 1) ans = Math.max(ans, j - i + 1);
                else if (fc.size() == 2) {
                    Iterator<Integer> it = fc.keySet().iterator();
                    int a = it.next(), b = it.next();
                    int lo = Math.min(a, b), hi = Math.max(a, b);
                    if (hi == 2L * lo) ans = Math.max(ans, j - i + 1);
                }
            }
        }
        return ans;
    }
}

