var longestFrequencyBalance = function(nums) {
    const n = nums.length;
    let ans = 1;
    for (let i = 0; i < n; i++) {
        const cnt = new Map(), fc = new Map();
        let d = 0;
        for (let j = i; j < n; j++) {
            const x = nums[j];
            const f = cnt.get(x) || 0;
            if (f === 0) d++;
            else {
                fc.set(f, fc.get(f) - 1);
                if (fc.get(f) === 0) fc.delete(f);
            }
            cnt.set(x, f + 1);
            fc.set(f + 1, (fc.get(f + 1) || 0) + 1);
            if (d === 1) ans = Math.max(ans, j - i + 1);
            else if (fc.size === 2) {
                const [a, b] = [...fc.keys()].sort((p, q) => p - q);
                if (b === 2 * a) ans = Math.max(ans, j - i + 1);
            }
        }
    }
    return ans;
};
